(function () {
    async function switchLorebookStatus(activeRole) {
        const books = await getCharWorldbookNames('current');
        const currentBookName = books.primary; 

        const suffixMap = { "转校生": "a", "普通学生": "b", "学生会成员": "c", "班主任": "d", "custom": "e" };
        const activeEntryName = `{user}${suffixMap[activeRole]}`;
        const groupEntries = ["{user}a", "{user}b", "{user}c", "{user}d", "{user}e"];

        await updateWorldbookWith(currentBookName, (entries) => {
            return entries.map(entry => {
                if (entry.name === activeEntryName) {
                    return { ...entry, enabled: true, disable: false };
                }
                return groupEntries.includes(entry.name) ? { ...entry, enabled: false, disable: true } : entry;
            });
        }, { render: 'immediate' });
    }

    async function writeCustomContent(iframeDoc, roleSelect) {
        if (!roleSelect || roleSelect.value !== "custom") return;

        let finalContent = "";
        const iframeWin = iframeDoc.defaultView;

        while (!finalContent) {
            if (iframeWin && iframeWin.lastCreatedMessage && iframeWin.lastCreatedMessage.trim() !== "") {
                finalContent = iframeWin.lastCreatedMessage.trim();
            } else {
                await new Promise(resolve => setTimeout(resolve, 10));
            }
        }

        alert("【核心提示】成功读取自定义角色，当前值为:\n" + finalContent + "\n数据安全，准备注入世界书...");

        const books = await getCharWorldbookNames('current');
        const currentBookName = books.primary;

        await updateWorldbookWith(currentBookName, (entries) => {
            return entries.map(entry => {
                if (entry.name === "{user}e") {
                    return { ...entry, content: finalContent };
                }
                return entry;
            });
        }, { render: 'immediate' });
    }

    function onRoleChange(e) {
        if (e.target.value !== "custom") {
            switchLorebookStatus(e.target.value);
        } else {
            switchLorebookStatus("custom");
        }
    }

    function createBtnHandler(iframeDoc, roleSelect) {
        return function onBtnClick() {
            writeCustomContent(iframeDoc, roleSelect);
        };
    }

    let currentBtnHandler = null;
    const mainDoc = window.parent.document;

    const observer = new MutationObserver(() => {
        const targetIframe = mainDoc.querySelector('iframe[id^="TH-message-"]');
        if (!targetIframe) return;

        const iframeDoc = targetIframe.contentWindow.document;
        const roleSelect = iframeDoc.getElementById('role');
        const generateBtn = iframeDoc.querySelector('button');

        if (!roleSelect) return;

        roleSelect.removeEventListener('change', onRoleChange);
        roleSelect.addEventListener('change', onRoleChange);

        if (generateBtn) {
            if (currentBtnHandler) {
                generateBtn.removeEventListener('click', currentBtnHandler);
            }
            currentBtnHandler = createBtnHandler(iframeDoc, roleSelect);
            generateBtn.addEventListener('click', currentBtnHandler);
        }
    });

    observer.observe(mainDoc.body, { childList: true, subtree: true });
})();

